css:
.kts { font-family: Arial, Helvetica, sans-serif; font-size: 12px; color: #111; }
.kts table { width: 100%; border-collapse: collapse; }
.kts-head td { vertical-align: top; padding: 0 0 8px; }
.kts-co { font-size: 15px; font-weight: bold; }
.kts-title { font-size: 13px; letter-spacing: 1px; text-transform: uppercase; color: #444; }
.kts-right { text-align: right; }
.kts-no { font-size: 15px; font-weight: bold; }
.kts-flag { color: #b91c1c; font-weight: bold; }
.kts-route { border: 1.5px solid #111; margin: 4px 0 10px; }
.kts-route td { padding: 8px 10px; font-size: 13px; width: 45%; }
.kts-route td.kts-arrow { width: 10%; text-align: center; font-size: 22px; }
.kts-lbl { font-size: 10px; text-transform: uppercase; letter-spacing: 1px; color: #555; }
.kts-items th { border-bottom: 1.5px solid #111; text-align: left; padding: 5px 4px; font-size: 11px; text-transform: uppercase; }
.kts-items td { border-bottom: 1px solid #ccc; padding: 5px 4px; vertical-align: top; }
.kts-items tfoot td { border-bottom: none; border-top: 1.5px solid #111; }
.kts-items .r { text-align: right; white-space: nowrap; }
.kts-items .c { text-align: center; width: 6%; }
.kts-code { color: #555; font-size: 10px; }
.kts-note { margin-top: 10px; padding: 6px 8px; border: 1px dashed #999; }
.kts-sign { margin-top: 28px; }
.kts-sign td { width: 33%; vertical-align: top; padding-right: 10px; font-size: 11px; color: #333; }
.kts-items tr { page-break-inside: avoid; }
